import { getProgramName } from './program-name.mjs';

export class CliExit extends Error {
  constructor(code, streamName, output) {
    super(output);
    this.code = code;
    this.streamName = streamName;
    this.output = output;
  }
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A       Comma-separated numbers\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

function looksLikeNegativeNumber(token) {
  return /^-\d+$|^-\d*\.\d+$/.test(token);
}

function canConsumeValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return looksLikeNegativeNumber(token);
}

export function parseArgs(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  let aValue;
  let sawA = false;
  const unknownTokens = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, 'stdout', formatHelp(programName));
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];
      if (!canConsumeValue(nextToken)) {
        throw new CliExit(2, 'stderr', formatError(programName, 'argument --a: expected one argument'));
      }

      sawA = true;
      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      sawA = true;
      aValue = token.slice(4);
      continue;
    }

    unknownTokens.push(token);
  }

  if (!sawA) {
    throw new CliExit(2, 'stderr', formatError(programName, 'the following arguments are required: --a'));
  }

  if (unknownTokens.length > 0) {
    throw new CliExit(2, 'stderr', formatError(programName, `unrecognized arguments: ${unknownTokens.join(' ')}`));
  }

  return { a: aValue };
}

