import { CliExit, parseArgs } from '../cli/argparse.mjs';
import { formatPythonValue } from '../format/python-repr.mjs';
import { bucketize } from '../iter/bucketize.mjs';
import { PythonIntParseError, parseCommaSeparatedIntegers } from './python-int.mjs';

function formatPythonValueError(error) {
  return `Traceback (most recent call last):\n  File "test5.py", line 8, in <module>\nValueError: ${error.message}\n`;
}

export function runTest5(argv, scriptPath) {
  const args = parseArgs(argv, scriptPath);
  const numbers = parseCommaSeparatedIntegers(args.a);
  const result = bucketize(numbers, (value) => value % 2n === 0n);
  return formatPythonValue(result);
}

export function main({
  argv = process.argv.slice(2),
  scriptPath = process.argv[1],
  stdout = process.stdout,
  stderr = process.stderr,
} = {}) {
  try {
    const output = runTest5(argv, scriptPath);
    stdout.write(`${output}\n`);
    return 0;
  } catch (error) {
    if (error instanceof CliExit) {
      const stream = error.streamName === 'stdout' ? stdout : stderr;
      stream.write(error.output);
      process.exitCode = error.code;
      return error.code;
    }

    if (error instanceof PythonIntParseError) {
      stderr.write(formatPythonValueError(error));
      process.exitCode = 1;
      return 1;
    }

    throw error;
  }
}

